  fun suggestionsFor(location: String): List<AartiItem> {
    val normalized = location.lowercase()
    return when {
      normalized.contains("pune") || normalized.contains("mumbai") || normalized.contains("maharashtra") -> aartis.filter { it.category == "Ganesh" || "Marathi" in it.languages || it.category == "Shiva" }
      normalized.contains("puri") || normalized.contains("odisha") -> aartis.filter { it.category == "Vishnu" || "Sanskrit" in it.languages }
      normalized.contains("varanasi") || normalized.contains("uttar pradesh") -> aartis.filter { it.category == "Shiva" || it.deity == "Rama" }
      normalized.contains("tirupati") || normalized.contains("andhra") -> aartis.filter { it.category == "Vishnu" || it.deity == "Krishna" }
      normalized.contains("bengaluru") || normalized.contains("karnataka") -> aartis.filter { "Kannada" in it.languages || it.category == "Vishnu" || it.category == "Shiva" || it.category == "Morning" }
      normalized.contains("chennai") || normalized.contains("tamil nadu") -> aartis.filter { "Tamil" in it.languages || it.category == "Shiva" || it.category == "Vishnu" }
      normalized.contains("ahmedabad") || normalized.contains("gujarat") -> aartis.filter { "Gujarati" in it.languages || it.category == "Devi" || it.category == "Krishna" }
      normalized.contains("hyderabad") || normalized.contains("telangana") -> aartis.filter { "Telugu" in it.languages || it.category == "Vishnu" || it.category == "Shiva" }
      normalized.contains("kolkata") || normalized.contains("bengal") -> aartis.filter { "Bengali" in it.languages || it.category == "Devi" || it.category == "Krishna" }
      normalized.contains("himachal") || normalized.contains("shimla") || normalized.contains("kangra") -> aartis.filter { it.category == "Devi" || it.category == "Shiva" || it.category == "Hanuman" }
      else -> aartis
    }
  }
}
